      curiosidad: "La alimentación de estas aves puede contribuir a dispersar semillas, transportar frutos y regular su disponibilidad en los bosques.",
      estadoConservacion: "Preocupación menor",
      narracionAudioguia: "Conoce a Guacamayo azul y amarillo. El guacamayo azulamarillo (Ara ararauna), también conocido como guacamayo azul y amarillo, papagayo amarillo o paraba azul amarillo, es una especie de ave psittaciforme de la familia de los loros endémica de América del Sur. Su área de distribución comprende desde Panamá hasta el norte de Paraguay y Bolivia, pasando por toda la cuenca amazónica. En cautividad se reproducen fácilmente; en libertad viven en grupos de 25-30 ejemplares. Fotografía sin flash y evita gritar o silbar para provocar respuestas.",
      distribucion: "El guacamayo azulamarillo (Ara ararauna), también conocido como guacamayo azul y amarillo, papagayo amarillo o paraba azul amarillo, es una especie de ave psittaciforme de la familia de los loros endémica de América del Sur.",
      fuente: "Inventario público de OSINFOR · Huachipa",
      descripcion: "El guacamayo azulamarillo (Ara ararauna), también conocido como guacamayo azul y amarillo, papagayo amarillo o paraba azul amarillo, es una especie de ave psittaciforme de la familia de los loros endémica de América del Sur. Su área de distribución comprende desde Panamá hasta el norte de Paraguay y Bolivia, pasando por toda la cuenca amazónica. En cautividad se reproducen fácilmente; en libertad viven en grupos de 25-30 ejemplares.",
      reconocimiento: "Observa el pico curvado, los colores de la frente, las alas y la cola. Estos detalles ayudan a distinguir guacamayos, loros y pericos.",
      reproduccion: "Ovípara: se reproduce por huevos. El nido, la incubación y el cuidado de las crías dependen de la especie. La presencia de huevos o crías en el parque debe confirmarse con su equipo.",
      rolEcologico: "La alimentación de estas aves puede contribuir a dispersar semillas, transportar frutos y regular su disponibilidad en los bosques.",
      recomendaciones: [
        "Fotografía sin flash y evita gritar o silbar para provocar respuestas.",
        "No ofrezcas semillas ni galletas al ave.",
        "Mira el pico y las patas para reconocer adaptaciones a la alimentación y al desplazamiento.",
